{{setVar 'emailBusca' (bodyRaw 'email')}}{{setVar 'senhaBusca' (bodyRaw 'senha')}}{{setVar 'usuarioEncontrado' (find (dataRaw 'usuariosCadastrados') (object email=@emailBusca senha=@senhaBusca))}}{{#if @usuarioEncontrado}}{{setData 'set' 'usuarioAutenticadoAtual' 'idUsuarioAtual' (objectPath @usuarioEncontrado 'id')}}{
  "success": true,
  "message": "Login realizado com sucesso",
  "data": {
    "id": {{objectPath @usuarioEncontrado 'id'}},
    "name": "{{objectPath @usuarioEncontrado 'name'}}",
    "email": "{{objectPath @usuarioEncontrado 'email'}}",
    "pontosSaldo": {{objectPath @usuarioEncontrado 'pontosSaldo'}},
    "qrCode": "{{objectPath @usuarioEncontrado 'qrCode'}}",
    "token": "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9",
