{{setVar 'idAtual' (dataRaw 'usuarioAutenticadoAtual' 'idUsuarioAtual')}}{{setVar 'agora' (now)}}{{setVar 'usuarioAtual' (find (dataRaw 'usuariosCadastrados') (object id=@idAtual))}}{{setVar 'emailNovo' (bodyRaw 'email' '')}}{{setVar 'emailEmUso' false}}{{#if @emailNovo}}{{setVar 'donoDoEmail' (find (dataRaw 'usuariosCadastrados') (object email=@emailNovo))}}{{#if @donoDoEmail}}{{#unless (eq (objectPath @donoDoEmail 'id') @idAtual)}}{{setVar 'emailEmUso' true}}{{/unless}}{{/if}}{{/if}}{{#if @usuarioAtual}}{{#if @emailEmUso}}{{status 409}}{
  "success": false,
  "message": "Este email ja esta em uso por outro usuario",
  "debug": {
    "emailRecebido": "{{@emailNovo}}"
  }
}{{else}}{{#each (dataRaw 'usuariosCadastrados')}}{{#if (eq this.id @../idAtual)}}{{setVar 'atualizado' (objectMerge this (object name=(bodyRaw 'name' this.name) email=(bodyRaw 'email' this.email) senha=(bodyRaw 'senha' this.senha) telefone=(bodyRaw 'telefone' this.telefone) cpf=(bodyRaw 'cpf' this.cpf) dataNascimento=(bodyRaw 'dataNascimento' this.dataNascimento) genero=(bodyRaw 'genero' this.genero) ativo=(bodyRaw 'ativo' this.ativo) qrCode=(bodyRaw 'qrCode' this.qrCode) nivelMembro=(bodyRaw 'nivelMembro' this.nivelMembro) ultimoAcesso=(bodyRaw 'ultimoAcesso' this.ultimoAcesso) endereco=(object logradouro=(bodyRaw 'endereco.logradouro' this.endereco.logradouro) numero=(bodyRaw 'endereco.numero' this.endereco.numero) bairro=(bodyRaw 'endereco.bairro' this.endereco.bairro) cidade=(bodyRaw 'endereco.cidade' this.endereco.cidade) uf=(bodyRaw 'endereco.uf' this.endereco.uf) cep=(bodyRaw 'endereco.cep' this.endereco.cep)) updatedAt=@../agora))}}{{setData 'set' 'usuariosCadastrados' (concat @index '') @atualizado}}{
  "success": true,
  "message": "Dados atualizados com sucesso",
  "data": {{{stringify @atualizado}}}
}{{/if}}{{/each}}{{/if}}{{else}}{{status 401}}{
  "success": false,
  "message": "Nenhum usuario autenticado. Faca login antes de alterar os dados"
}{{/if}}

{{setVar 'idAtual' (dataRaw 'usuarioAutenticadoAtual' 'idUsuarioAtual')}}{{setVar 'emailDestino' (bodyRaw 'emailDestino')}}{{#unless @emailDestino}}{{setVar 'emailDestino' (bodyRaw 'email')}}{{/unless}}{{setVar 'pontosTransferir' (bodyRaw 'valorPontos')}}{{#unless @pontosTransferir}}{{setVar 'pontosTransferir' (bodyRaw 'pontos')}}{{/unless}}{{#unless @pontosTransferir}}{{setVar 'pontosTransferir' (bodyRaw 'pontosTransferidos')}}{{/unless}}{{#unless @pontosTransferir}}{{setVar 'pontosTransferir' (bodyRaw 'quantidade')}}{{/unless}}{{setVar 'agora' (now)}}{{setVar 'usuarioAtual' (find (dataRaw 'usuariosCadastrados') (object id=@idAtual))}}{{setVar 'usuarioDestino' (find (dataRaw 'usuariosCadastrados') (object email=@emailDestino))}}{{setVar 'nomeAtual' (objectPath @usuarioAtual 'name')}}{{setVar 'saldoOrigem' (objectPath @usuarioAtual 'pontosSaldo')}}{{#if @usuarioAtual}}{{#if @usuarioDestino}}{{setVar 'idDestino' (objectPath @usuarioDestino 'id')}}{{setVar 'nomeDestino' (objectPath @usuarioDestino 'name')}}{{#if (eq @idDestino @idAtual)}}{{status 400}}{
  "success": false,
  "message": "Nao e possivel transferir pontos para o proprio usuario"
}{{else}}{{#if (gt @pontosTransferir 0)}}{{#if (gte @saldoOrigem @pontosTransferir)}}{{#each (dataRaw 'usuariosCadastrados')}}{{#if (eq this.id @../idDestino)}}{{setVar 'saldoAtualDestino' (add this.pontosSaldo @../pontosTransferir)}}{{setVar 'proximoIdMovDestino' (add (len this.movimentacoes) 1)}}{{setData 'set' 'usuariosCadastrados' (concat @index '.pontosSaldo') @saldoAtualDestino}}{{setData 'inc' 'usuariosCadastrados' (concat @index '.totalPontosGanhos') @../pontosTransferir}}{{setData 'set' 'usuariosCadastrados' (concat @index '.updatedAt') @../agora}}{{setData 'push' 'usuariosCadastrados' (concat @index '.movimentacoes') (object id=@proximoIdMovDestino idUsuario=@../idDestino idProduto=null tipo='credito' valorPontos=@../pontosTransferir descricao=(concat 'Transferencia recebida de ' @../nomeAtual) data=(now 'yyyy-MM-dd') createdAt=@../agora updatedAt=@../agora)}}{{/if}}{{#if (eq this.id @../idAtual)}}{{setVar 'saldoAnteriorOrigem' this.pontosSaldo}}{{setVar 'saldoAtualOrigem' (subtract this.pontosSaldo @../pontosTransferir)}}{{setVar 'proximoIdMovOrigem' (add (len this.movimentacoes) 1)}}{{setData 'set' 'usuariosCadastrados' (concat @index '.pontosSaldo') @saldoAtualOrigem}}{{setData 'inc' 'usuariosCadastrados' (concat @index '.pontosUtilizados') @../pontosTransferir}}{{setData 'set' 'usuariosCadastrados' (concat @index '.updatedAt') @../agora}}{{setData 'push' 'usuariosCadastrados' (concat @index '.movimentacoes') (object id=@proximoIdMovOrigem idUsuario=@../idAtual idProduto=null tipo='debito' valorPontos=@../pontosTransferir descricao=(concat 'Transferencia enviada para ' @../nomeDestino) data=(now 'yyyy-MM-dd') createdAt=@../agora updatedAt=@../agora)}}{
  "success": true,
  "message": "Transferencia realizada com sucesso",
  "data": {
    "idUsuarioOrigem": {{@../idAtual}},
    "nomeUsuarioOrigem": "{{@../nomeAtual}}",
    "idUsuarioDestino": {{@../idDestino}},
    "nomeUsuarioDestino": "{{@../nomeDestino}}",
    "emailDestino": "{{@../emailDestino}}",
    "pontosTransferidos": {{@../pontosTransferir}},
    "pontosSaldoAnteriorOrigem": {{@saldoAnteriorOrigem}},
    "pontosSaldoAtualOrigem": {{@saldoAtualOrigem}},
    "createdAt": "{{@../agora}}"
  }
}{{/if}}{{/each}}{{else}}{{status 400}}{
  "success": false,
  "message": "Saldo de pontos insuficiente para realizar a transferencia",
  "debug": {
    "pontosSolicitados": {{@pontosTransferir}},
    "pontosSaldoAtual": {{@saldoOrigem}}
  }
}{{/if}}{{else}}{{status 400}}{
  "success": false,
  "message": "Informe uma quantidade de pontos maior que zero no campo valorPontos",
  "debug": {
    "valorRecebido": {{#if @pontosTransferir}}{{@pontosTransferir}}{{else}}null{{/if}},
    "camposAceitos": ["valorPontos", "pontos", "pontosTransferidos", "quantidade"]
  }
}{{/if}}{{/if}}{{else}}{{status 404}}{
  "success": false,
  "message": "Usuario destinatario nao encontrado",
  "debug": {
    "emailDestinoRecebido": "{{@emailDestino}}"
  }
}{{/if}}{{else}}{{status 401}}{
  "success": false,
  "message": "Usuario de origem nao autenticado. Faca login antes de transferir pontos"
}{{/if}}

