{{setVar 'idAtual' (dataRaw 'usuarioAutenticadoAtual' 'idUsuarioAtual')}}{{setVar 'agora' (now)}}{{setVar 'usuarioAtual' (find (dataRaw 'usuariosCadastrados') (object id=@idAtual))}}{{setData 'set' 'resgateEmAndamento' 'itens' (array)}}{{setData 'set' 'resgateEmAndamento' 'total' 0}}{{setData 'set' 'resgateEmAndamento' 'itensInvalidos' 0}}{{setData 'set' 'resgateEmAndamento' 'quantidadesInvalidas' 0}}{{setData 'set' 'resgateEmAndamento' 'indiceUsuario' -1}}{{setData 'set' 'resgateEmAndamento' 'proximoIdMov' 1}}{{#if (bodyRaw 'itens')}}{{#each (bodyRaw 'itens')}}{{setData 'push' 'resgateEmAndamento' 'itens' (object idProduto=this.idProduto quantidade=(bodyRaw (concat 'itens.' @index '.quantidade') 1))}}{{/each}}{{else}}{{#if (bodyRaw 'idProduto')}}{{setData 'push' 'resgateEmAndamento' 'itens' (object idProduto=(bodyRaw 'idProduto') quantidade=(bodyRaw 'quantidade' 1))}}{{/if}}{{/if}}{{#each (dataRaw 'resgateEmAndamento' 'itens')}}{{setVar 'prod' (find (dataRaw 'produtos') (object id=this.idProduto))}}{{#unless (gt this.quantidade 0)}}{{setData 'inc' 'resgateEmAndamento' 'quantidadesInvalidas' 1}}{{/unless}}{{#if @prod}}{{setData 'inc' 'resgateEmAndamento' 'total' (multiply (objectPath @prod 'valorPontos') this.quantidade)}}{{else}}{{setData 'inc' 'resgateEmAndamento' 'itensInvalidos' 1}}{{/if}}{{/each}}{{setVar 'itensResgate' (dataRaw 'resgateEmAndamento' 'itens')}}{{setVar 'qtdItens' (len @itensResgate)}}{{setVar 'total' (dataRaw 'resgateEmAndamento' 'total')}}{{setVar 'invalidos' (dataRaw 'resgateEmAndamento' 'itensInvalidos')}}{{setVar 'qtdInvalidas' (dataRaw 'resgateEmAndamento' 'quantidadesInvalidas')}}{{setVar 'saldoAnterior' (objectPath @usuarioAtual 'pontosSaldo')}}{{setVar 'saldoAtual' (subtract @saldoAnterior @total)}}{{#if @usuarioAtual}}{{#if (gt @qtdItens 0)}}{{#if (eq @invalidos 0)}}{{#if (eq @qtdInvalidas 0)}}{{#if (gte @saldoAnterior @total)}}{{setVar 'idResgate' (int 1000 9999)}}{{#each (dataRaw 'usuariosCadastrados')}}{{#if (eq this.id @../idAtual)}}{{setData 'set' 'resgateEmAndamento' 'indiceUsuario' @index}}{{setData 'set' 'resgateEmAndamento' 'proximoIdMov' (add (len this.movimentacoes) 1)}}{{/if}}{{/each}}{{setVar 'idxUsuario' (dataRaw 'resgateEmAndamento' 'indiceUsuario')}}{{setVar 'baseIdMov' (dataRaw 'resgateEmAndamento' 'proximoIdMov')}}{{#each @itensResgate}}{{setVar 'prod' (find (dataRaw 'produtos') (object id=this.idProduto))}}{{setData 'push' 'usuariosCadastrados' (concat @../idxUsuario '.movimentacoes') (object id=(add @../baseIdMov @index) idUsuario=@../idAtual idResgate=@../idResgate idProduto=this.idProduto nomeProduto=(objectPath @prod 'name') quantidade=this.quantidade tipo='debito' valorPontos=(multiply (objectPath @prod 'valorPontos') this.quantidade) descricao=(concat 'Resgate solicitado: ' (objectPath @prod 'name') ' (x' this.quantidade ')') data=(now 'yyyy-MM-dd') createdAt=@../agora updatedAt=@../agora)}}{{/each}}{{setData 'set' 'usuariosCadastrados' (concat @idxUsuario '.pontosSaldo') @saldoAtual}}{{setData 'inc' 'usuariosCadastrados' (concat @idxUsuario '.pontosUtilizados') @total}}{{setData 'set' 'usuariosCadastrados' (concat @idxUsuario '.updatedAt') @agora}}{
  "success": true,
  "message": "Resgate criado com sucesso",
  "data": {
    "idResgate": {{@idResgate}},
    "idUsuario": {{@idAtual}},
    "quantidadeItens": {{@qtdItens}},
    "itens": [
    {{#each @itensResgate}}{{setVar 'p' (find (dataRaw 'produtos') (object id=this.idProduto))}}{
      "idProduto": {{this.idProduto}},
      "nomeProduto": "{{objectPath @p 'name'}}",
      "quantidade": {{this.quantidade}},
      "valorPontosUnitario": {{objectPath @p 'valorPontos'}},
      "valorPontosTotal": {{multiply (objectPath @p 'valorPontos') this.quantidade}}
    }{{#unless @last}},
    {{/unless}}{{/each}}
    ],
    "pontosUtilizados": {{@total}},
    "pontosSaldoAnterior": {{@saldoAnterior}},
    "pontosSaldoAtual": {{@saldoAtual}},
    "status": "pendente",
    "dataCriacao": "{{@agora}}",
    "dataConfirmacao": null,
    "createdAt": "{{@agora}}",
    "updatedAt": "{{@agora}}"
  }
}{{else}}{{status 400}}{
  "success": false,
  "message": "Saldo de pontos insuficiente para realizar o resgate",
  "debug": {
    "pontosNecessarios": {{@total}},
    "pontosSaldoAtual": {{@saldoAnterior}}
  }
}{{/if}}{{else}}{{status 400}}{
  "success": false,
  "message": "Todo item do resgate precisa de uma quantidade maior que zero",
  "debug": {
    "itensComQuantidadeInvalida": {{@qtdInvalidas}}
  }
}{{/if}}{{else}}{{status 404}}{
  "success": false,
  "message": "Produto nao encontrado para o resgate informado",
  "debug": {
    "itensNaoEncontrados": {{@invalidos}},
    "itensRecebidos": {{{stringify @itensResgate}}}
  }
}{{/if}}{{else}}{{status 400}}{
  "success": false,
  "message": "Informe ao menos um item no resgate",
  "debug": {
    "formatosAceitos": ["itens: [{ idProduto, quantidade }]", "idProduto (item unico)"]
  }
}{{/if}}{{else}}{{status 401}}{
  "success": false,
  "message": "Nenhum usuario autenticado. Faca login antes de resgatar"
}{{/if}}

{{setVar 'pontosCredito' (bodyRaw 'pontosBonificados')}}{{setVar 'idProdutoMov' (bodyRaw 'idProduto')}}{{setVar 'agora' (now)}}{{setVar 'idAtual' (dataRaw 'usuarioAutenticadoAtual' 'idUsuarioAtual')}}{{#each (dataRaw 'usuariosCadastrados')}}{{#if (eq this.id @../idAtual)}}{{setVar 'saldoAnterior' this.pontosSaldo}}{{setVar 'saldoAtual' (add @saldoAnterior @../pontosCredito)}}{{setVar 'proximoIdMov' (add (len this.movimentacoes) 1)}}{{setData 'set' 'usuariosCadastrados' (concat @index '.pontosSaldo') @saldoAtual}}{{setData 'inc' 'usuariosCadastrados' (concat @index '.totalPontosGanhos') @../pontosCredito}}{{setData 'set' 'usuariosCadastrados' (concat @index '.updatedAt') @../agora}}{{setData 'push' 'usuariosCadastrados' (concat @index '.movimentacoes') (object id=@proximoIdMov idUsuario=@../idAtual idProduto=@../idProdutoMov tipo='credito' valorPontos=@../pontosCredito descricao='Bonificacao de pontos por compra em parceiro farmaceutico' data=(now 'yyyy-MM-dd') createdAt=@../agora updatedAt=@../agora)}}{
