  "data": {
    "idUsuario": {{@../idAtual}},
    "idEstabelecimento": {{urlParam 'id'}},
    "idProduto": {{@../idProdutoMov}},
    "pontosBonificados": {{@../pontosCredito}},
    "pontosSaldoAnterior": {{@saldoAnterior}},
    "pontosSaldoAtual": {{@saldoAtual}},
    "nomeEstabelecimento": "Drogasil",
    "motivo": "Compra bonificada em parceiro de farmacia",
    "createdAt": "{{@../agora}}",
    "updatedAt": "{{@../agora}}"
  }
}{{/if}}{{/each}}
